from intervals import merge_intervals
import copy

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# ---------- helpers: obviously-correct reference model ----------

def point_set(intervals):
    s = set()
    for a, b in intervals:
        s.update(range(a, b + 1))
    return s


def reference_merge(intervals):
    for a, b in intervals:
        if a > b:
            raise ValueError
    pts = point_set(intervals)
    if not pts:
        return []
    out = []
    cur_start = cur_end = min(pts)
    for p in sorted(pts):
        if p == cur_start and p == cur_end:
            continue
        if p <= cur_end + 1 and p >= cur_start:
            # p is next integer; check continuity: if gap, split
            if p == cur_end + 1 or p <= cur_end:
                cur_end = max(cur_end, p)
            else:
                out.append((cur_start, cur_end))
                cur_start = cur_end = p
        else:
            out.append((cur_start, cur_end))
            cur_start = cur_end = p
        # simpler: if p > cur_end + 1 -> gap; but since we iterate sorted pts,
        # gap means p > cur_end + 1
    # Recompute correctly via gap scan to avoid logic slip:
    out = []
    sorted_pts = sorted(pts)
    cur_start = sorted_pts[0]
    cur_end = sorted_pts[0]
    for p in sorted_pts[1:]:
        if p == cur_end + 1 or p <= cur_end:
            cur_end = max(cur_end, p)
        else:
            out.append((cur_start, cur_end))
            cur_start = cur_end = p
    out.append((cur_start, cur_end))
    return out


valid_interval = st.tuples(st.integers(-10, 10), st.integers(-10, 10)).map(
    lambda p: (min(p[0], p[1]), max(p[0], p[1]))
)
valid_lists = st.lists(valid_interval, min_size=0, max_size=10)


# ---------- spec examples ----------

def test_example_basic_merge():
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]


def test_example_touching_merges():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]


def test_example_adjacent_stays_separate():
    assert merge_intervals([(1, 3), (4, 5)]) == [(1, 3), (4, 5)]


def test_example_unsorted_input_sorted_output():
    assert merge_intervals([(5, 7), (1, 2)]) == [(1, 2), (5, 7)]


def test_example_empty():
    assert merge_intervals([]) == []


def test_example_invalid_raises():
    with pytest.raises(ValueError):
        merge_intervals([(3, 1)])


# ---------- explicit touching / adjacency / containment ----------

def test_touching_at_single_point_merges():
    assert merge_intervals([(1, 2), (2, 2)]) == [(1, 2)]
    assert merge_intervals([(2, 2), (2, 5)]) == [(2, 5)]
    assert merge_intervals([(0, 0), (0, 0)]) == [(0, 0)]


def test_adjacent_does_not_merge():
    assert merge_intervals([(1, 2), (3, 4)]) == [(1, 2), (3, 4)]
    assert merge_intervals([(0, 0), (1, 1)]) == [(0, 0), (1, 1)]
    assert merge_intervals([(-5, -3), (-2, 0)]) == [(-5, -3), (-2, 0)]


def test_contained_interval_absorbed():
    assert merge_intervals([(1, 10), (2, 3)]) == [(1, 10)]
    assert merge_intervals([(2, 3), (1, 10)]) == [(1, 10)]
    assert merge_intervals([(1, 5), (1, 5)]) == [(1, 5)]


def test_transitive_chain_collapses():
    assert merge_intervals([(1, 2), (2, 3), (3, 4), (5, 6)]) == [(1, 4), (5, 6)]
    assert merge_intervals([(1, 2), (3, 4), (2, 3)]) == [(1, 4)]


def test_single_point_valid():
    assert merge_intervals([(2, 2)]) == [(2, 2)]
    assert merge_intervals([(5, 5), (5, 5), (6, 6)]) == [(5, 5), (6, 6)]


def test_negative_and_zero_intervals():
    assert merge_intervals([(-10, -5), (-6, -1)]) == [(-10, -1)]
    assert merge_intervals([(-3, -3), (0, 0)]) == [(-3, -3), (0, 0)]


def test_invalid_any_position_raises():
    with pytest.raises(ValueError):
        merge_intervals([(1, 2), (5, 4)])
    with pytest.raises(ValueError):
        merge_intervals([(5, 4), (1, 2)])
    with pytest.raises(ValueError):
        merge_intervals([(1, 2), (3, 3), (9, 8)])


def test_output_is_new_list_of_tuples():
    inp = [(1, 3), (2, 4)]
    res = merge_intervals(inp)
    assert res == [(1, 4)]
    assert res is not inp
    assert all(type(x) is tuple for x in res)


def test_input_not_mutated():
    inp = [(5, 7), (1, 3), (2, 6)]
    snapshot = copy.deepcopy(inp)
    merge_intervals(inp)
    assert inp == snapshot


# ---------- property-based tests ----------

@given(valid_lists)
def test_property_output_sorted_by_start(intervals):
    res = merge_intervals(intervals)
    assert [s for s, _ in res] == sorted(s for s, _ in res)


@given(valid_lists)
def test_property_output_disjoint_strict_gap(intervals):
    res = merge_intervals(intervals)
    for (s1, e1), (s2, e2) in zip(res, res[1:]):
        assert s2 > e1, f"{res} not strictly disjoint"
        assert s1 <= e1 and s2 <= e2


@given(valid_lists)
def test_property_coverage_preserved(intervals):
    res = merge_intervals(intervals)
    assert point_set(res) == point_set(intervals)


@given(valid_lists)
def test_property_equivalence_to_pointset_reference(intervals):
    assert merge_intervals(intervals) == reference_merge(intervals)


@given(valid_lists)
def test_property_idempotence(intervals):
    once = merge_intervals(intervals)
    assert merge_intervals(once) == once
    assert merge_intervals(list(once)) == once


@given(valid_lists)
def test_property_order_independence(intervals):
    res1 = merge_intervals(intervals)
    res2 = merge_intervals(list(reversed(intervals)))
    assert res1 == res2


@given(st.lists(valid_interval, min_size=0, max_size=6), st.integers(-10, 10), st.integers(-10, 10))
def test_property_duplicate_does_not_change_result(intervals, a, b):
    dup = (min(a, b), max(a, b))
    assert merge_intervals(intervals + [dup, dup]) == merge_intervals(intervals + [dup])


@given(valid_lists)
def test_property_output_endpoints_come_from_input(intervals):
    res = merge_intervals(intervals)
    starts = {s for s, _ in intervals}
    ends = {e for _, e in intervals}
    for s, e in res:
        assert s in starts
        assert e in ends


@given(valid_lists)
def test_property_no_two_outputs_can_merge(intervals):
    res = merge_intervals(intervals)
    for i in range(len(res)):
        for j in range(i + 1, len(res)):
            a1, b1 = res[i]
            a2, b2 = res[j]
            # disjoint closed intervals share no point
            assert b1 < a2 or b2 < a1


@given(valid_lists)
def test_property_input_never_mutated(intervals):
    snapshot = copy.deepcopy(intervals)
    merge_intervals(intervals)
    assert intervals == snapshot


@given(st.lists(st.tuples(st.integers(-8, 8), st.integers(-8, 8)), min_size=1, max_size=8))
def test_property_invalid_raises_valueerror(intervals):
    assume(any(s > e for s, e in intervals))
    with pytest.raises(ValueError):
        merge_intervals(intervals)


@given(st.lists(valid_interval, min_size=0, max_size=5))
def test_property_empty_and_singleton(intervals):
    if len(intervals) == 0:
        assert merge_intervals(intervals) == []
    if len(intervals) == 1:
        assert merge_intervals(intervals) == intervals
